fn push_rules_rule_4528(rules: &mut Vec<RubiRule>) {
    rubi_symb!(
        capital_a__,
        capital_b__,
        a__,
        b__,
        c__,
        d__,
        m_,
        n_,
        p_,
        x_,
        e__,
        f__
    );
    rules.push(rubi_rule!(
        order: 4528,
        source: "Int[(a_+b_.*csc[e_.+f_.*x_])^m_.*(c_+d_.*csc[e_.+f_.*x_])^n_.*(A_.+B_.*csc[e_.+f_.*x_])^p_.,x_Symbol] :=
          (-a*c)^m \\[Star] Int[Cos[e+f*x]^(2*m)*(d+c*Sin[e+f*x])^(n-m)*(B+A*Sin[e+f*x])^p/Sin[e+f*x]^(m+n+p),x] /;
        FreeQ[{a,b,c,d,e,f,A,B,n,p},x] && EqQ[b*c+a*d,0] && EqQ[a^2-b^2,0] && IntegersQ[m,n,p]",
        desc: "Algebraic simplification",
        refs: [],
        pattern: (a__ + b__ * i_csc(e__ + f__ * x_)).pow(m_)
            * (c__ + d__ * i_csc(e__ + f__ * x_)).pow(n_)
            * (capital_a__ + capital_b__ * i_csc(e__ + f__ * x_)).pow(p_),
        with: [a__, b__, e__, f__, m_, c__, d__, n_, capital_a__, capital_b__, p_, x_],
        optional: [b__, e__, f__, m_, d__, n_, capital_a__, capital_b__, p_],
        when: {
            freeq!([a__, b__, c__, d__, e__, f__, capital_a__, capital_b__, n_, p_], x_)
                && eqq!(&b__ * &c__ + &a__ * &d__, 0)
                && eqq!(a__.pow(2) - b__.pow(2), 0)
                && integersq!([m_, n_, p_])
        },
        rhs: {
            let angle = &e__ + &f__ * x_;
            let sin = angle.sin();
            let payload = angle.cos().pow(Atom::num(2) * &m_)
                * (&d__ + &c__ * &sin).pow(&n_ - &m_)
                * (&capital_b__ + &capital_a__ * &sin).pow(&p_)
                / sin.pow(&m_ + &n_ + &p_);
            let recursive = rubi_rhs_int(&payload, x_);

            rubi_star((-&a__ * &c__).pow(&m_), recursive)
        },
    ));
}

