fn push_rules_rule_4680(rules: &mut Vec<RubiRule>) {
    rubi_symb!(c__, d__, e__, f__, m_, n_, x_);
    rules.push(rubi_rule!(
        order: 4680,
        source: "Int[(c_.+d_.*x_)^m_.*csc[e_.+f_.*x_]^n_.,x_Symbol] :=
          If[MatchQ[f,f1_.*Complex[0,j_]],
            If[MatchQ[e,e1_.+Pi/2],
              Unintegrable[(c+d*x)^m*Sech[I*(e-Pi/2)+I*f*x]^n,x],
            (-I)^n*Unintegrable[(c+d*x)^m*Csch[-I*e-I*f*x]^n,x]],
          If[MatchQ[e,e1_.+Pi/2],
            Unintegrable[(c+d*x)^m*Sec[e-Pi/2+f*x]^n,x],
          Unintegrable[(c+d*x)^m*Csc[e+f*x]^n,x]]] /;
        FreeQ[{c,d,e,f,m,n},x] && IntegerQ[n]",
        desc: "Mark the integral as unintegrable by Rubi's terminal rule.",
        refs: [],
        pattern: (c__ + d__ * x_).pow(m_) * i_csc(e__ + f__ * x_).pow(n_),
        with: [c__, d__, m_, e__, f__, n_, x_],
        optional: [c__, d__, m_, e__, f__, n_],
        when: {
            freeq!([c__, d__, e__, f__, m_, n_], x_) && integerq!(n_)
        },
        rhs: {
            let i = rubi_i();
            let linear = &c__ + &d__ * x_;
            let half_pi = Atom::var(Symbol::PI) / 2;
            let f_matches_complex_multiple = rubi_match_q(
                &f__,
                Atom::var(rubi_symbols().f1__) * rubi_i() * Atom::var(rubi_symbols().j_),
                &[rubi_symbols().f1__],
            );
            let e_matches_pi_shift = rubi_match_q(
                &e__,
                Atom::var(rubi_symbols().e1__) + Atom::var(Symbol::PI) / 2,
                &[rubi_symbols().e1__],
            );

            if f_matches_complex_multiple {
                if e_matches_pi_shift {
                    rubi_unintegrable(
                        linear.pow(&m_)
                            * (&i * (&e__ - &half_pi) + &i * &f__ * x_)
                                .sech()
                                .pow(&n_),
                        x_,
                    )
                } else {
                    (-&i).pow(&n_)
                        * rubi_unintegrable(
                            linear.pow(&m_)
                                * (-&i * &e__ - &i * &f__ * x_).csch().pow(&n_),
                            x_,
                        )
                }
            } else if e_matches_pi_shift {
                rubi_unintegrable(
                    linear.pow(&m_) * (&e__ - &half_pi + &f__ * x_).sec().pow(&n_),
                    x_,
                )
            } else {
                rubi_simp(&(rubi_unintegrable(
                    linear.pow(&m_) * (&e__ + &f__ * x_).csc().pow(&n_),
                    x_,
                )), x_)
            }
        },
    ));
}

