fn push_rules_rule_4664(rules: &mut Vec<RubiRule>) {
    rubi_symb!(capital_a__, capital_b__, a__, b__, c__, d__, x_, e__);
    rules.push(rubi_rule!(
        order: 4664,
        source: "Int[(A_+B_.*sec[d_.+e_.*x_])/(a_.+b_.*sec[d_.+e_.*x_]+c_.*sec[d_.+e_.*x_]^2),x_Symbol] :=
          Module[{q=Rt[b^2-4*a*c,2]},
          (B+(b*B-2*A*c)/q) \\[Star] Int[1/(b+q+2*c*Sec[d+e*x]),x] +
          (B-(b*B-2*A*c)/q) \\[Star] Int[1/(b-q+2*c*Sec[d+e*x]),x]] /;
        FreeQ[{a,b,c,d,e,A,B},x] && NeQ[b^2-4*a*c,0]",
        desc: "Algebraic expansion",
        refs: [],
        pattern: (capital_a__ + capital_b__ * i_sec(d__ + e__ * x_))
            / (a__ + b__ * i_sec(d__ + e__ * x_) + c__ * i_sec(d__ + e__ * x_).pow(2)),
        with: [capital_a__, capital_b__, d__, e__, a__, b__, c__, x_],
        optional: [capital_b__, a__, b__, d__, e__, c__],
        when: {
            freeq!([a__, b__, c__, d__, e__, capital_a__, capital_b__], x_)
                && neq!(b__.pow(2) - Atom::num(4) * &a__ * &c__, 0)
        },
        rhs: {
            let angle = &d__ + &e__ * x_;
            let sec = angle.sec();
            let q = rubi_rt(&(b__.pow(2) - Atom::num(4) * &a__ * &c__), 2);
            let first_integrand = Atom::num(1) / (&b__ + &q + Atom::num(2) * &c__ * &sec);
            let second_integrand = Atom::num(1) / (&b__ - &q + Atom::num(2) * &c__ * &sec);
            let first = rubi_rhs_int(&first_integrand, x_);
            let second = rubi_rhs_int(&second_integrand, x_);

            let first_coefficient =
                &capital_b__ + (&b__ * &capital_b__ - Atom::num(2) * &capital_a__ * &c__) / &q;
            let second_coefficient =
                &capital_b__ - (&b__ * &capital_b__ - Atom::num(2) * &capital_a__ * &c__) / q;
            rubi_star(first_coefficient, first)
                    + rubi_star(second_coefficient, second)
        },
    ));
}

